const dashboardConnections = new WeakMap();

// One fetch per revision and connection, regardless of the number of cards.
function connectDashboard(hass, listener) {
  const connection = hass.connection;
  let state = dashboardConnections.get(connection);
  if (!state) {
    state = { listeners: new Set(), hass, value: { status: "loading" }, revision: null,
      generation: 0, fetching: false, requested: false, closed: false };
    state.publish = (value) => {
      if (state.closed) return;
      state.value = value;
      for (const callback of state.listeners) callback(value);
    };
    state.refresh = async () => {
      state.requested = true;
      if (state.fetching || state.closed) return;
      state.fetching = true;
      try {
        while (state.requested && !state.closed) {
          state.requested = false;
          const generation = state.generation;
          try {
            const snapshot = await new AlertManagerApi(() => state.hass).call({
              type: "alert_manager/alerts/list",
            });
            if (!Array.isArray(snapshot?.alerts)) throw new Error("Invalid alert snapshot");
            if (generation === state.generation) state.publish({ status: "ready", snapshot });
          } catch (error) {
            if (generation === state.generation) state.publish({
              status: error?.code === "unauthorized" ? "admin" : "unavailable",
            });
          }
        }
      } finally {
        state.fetching = false;
      }
    };
    state.update = (next, force = false) => {
      state.hass = next;
      const sensor = next.states?.["sensor.alert_manager_main_active"];
      const monitoring = next.states?.["switch.alert_manager_main_monitoring"];
      const status = next.user?.is_admin !== true ? "admin"
        : connection.connected === false || !sensor || !monitoring
          || ["unavailable", "unknown"].includes(sensor.state)
          || ["unavailable", "unknown"].includes(monitoring.state) ? "unavailable"
          : monitoring.state === "off" ? "paused" : null;
      const revision = JSON.stringify([status, sensor?.state,
        sensor?.attributes?.alerts_revision, sensor?.attributes?.runtime?.startup]);
      if (!force && revision === state.revision) return;
      state.revision = revision;
      state.generation += 1;
      if (status) {
        state.requested = false;
        state.publish({ status });
      } else {
        if (state.value.status !== "ready") state.publish({ status: "loading" });
        void state.refresh();
      }
    };
    state.disconnected = () => {
      state.generation += 1;
      state.requested = false;
      state.publish({ status: "unavailable" });
    };
    state.ready = () => state.update(state.hass, true);
    connection.addEventListener("disconnected", state.disconnected);
    connection.addEventListener("ready", state.ready);
    dashboardConnections.set(connection, state);
  }
  state.listeners.add(listener);
  listener(state.value);
  state.update(hass);
  return {
    update: (next) => state.update(next),
    retry: () => state.update(state.hass, true),
    disconnect: () => {
      state.listeners.delete(listener);
      if (state.listeners.size) return;
      state.closed = true;
      connection.removeEventListener("disconnected", state.disconnected);
      connection.removeEventListener("ready", state.ready);
      dashboardConnections.delete(connection);
    },
  };
}

// Source: frontend-src/dashboard/translations.js
// Only the sections used by the card are embedded by the build. Status messages
// must remain readable even when the integration or connection is unavailable.
const dashboardLanguages = { en: englishDashboardSource, fr: frenchDashboardSource };

function dashboardText(language, key, params = {}) {
  const read = (source) => key.split(".").reduce((value, part) => value?.[part], source.config_panel);
  const text = read(dashboardLanguages[language?.split("-")[0]] ?? englishDashboardSource)
    ?? read(englishDashboardSource) ?? key;
  return String(text).replace(/\{([a-zA-Z0-9_]+)\}/g, (match, name) => (
    Object.hasOwn(params, name) ? String(params[name] ?? "") : match
  ));
}

// Source: frontend-src/dashboard/groups.js
const DASHBOARD_ICONS = Object.freeze({
  unavailable: "mdi:help-network-outline",
  connectivity: "mdi:lan-disconnect",
  battery: "mdi:battery-low",
  unifi: "mdi:router-wireless",
  execution_errors: "mdi:script-text-outline",
  flapping: "mdi:pulse",
  coherence: "mdi:check-network-outline",
  rule: "mdi:format-list-checks",
});

function dashboardGroups(alerts, label, hass) {
  const groups = new Map();
  for (const alert of alerts) {
    if (alert.acknowledged || !alert.active_since
      || (label && !alertLabelIds(alert, hass).includes(label))) continue;
    const key = alert.device_id ? `device:${alert.device_id}` : `alert:${alert.id}`;
    if (!groups.has(key)) groups.set(key, { key, alerts: [], latest: 0 });
    const group = groups.get(key);
    group.alerts.push(alert);
    group.latest = Math.max(group.latest, Date.parse(alert.active_since) || 0);
  }
  const compare = (a, b) => a < b ? -1 : a > b ? 1 : 0;
  return [...groups.values()].map((group) => {
    group.alerts.sort((a, b) => compare(a.id, b.id));
    group.types = [...new Set(group.alerts.map((alert) => alert.type))].sort(compare);
    return group;
  }).sort((a, b) => b.latest - a.latest || compare(a.key, b.key));
}

function dashboardTarget(group, label = "") {
  const alert = group.alerts[0];
  const params = new URLSearchParams(group.alerts.length === 1
    ? { alert: alert.id } : { device: alert.device_id });
  if (group.alerts.length > 1 && label) params.set("label", label);
  return `/alert-manager/overview?${params}`;
}

// Source: frontend-src/dashboard/editor.js
function validateDashboardConfig(config, language) {
  const max = config?.max_tiles ?? 5;
  if (!config || !Number.isInteger(max) || max < 1 || max > 100
    || (config.label !== undefined && typeof config.label !== "string")) {
    throw new Error(dashboardText(language, "dashboard.invalid_config"));
  }
  return { ...config, max_tiles: max };
}

class AlertManagerCardEditor extends HTMLElement {
  constructor() {
    super();
    this.attachShadow({ mode: "open" });
    this._form = document.createElement("ha-form");
    this.shadowRoot.append(this._form);
    this._form.schema = [
      { name: "max_tiles", required: true, selector: { number: { min: 1, max: 100, mode: "box" } } },
      { name: "label", selector: { label: {} } },
    ];
    this._form.addEventListener("value-changed", (event) => {
      event.stopPropagation();
      const config = { ...this._config, ...event.detail.value };
      if (!config.label) delete config.label;
      this._config = validateDashboardConfig(config, this._hass?.locale?.language);
      this.dispatchEvent(new CustomEvent("config-changed", {
        detail: { config: this._config }, bubbles: true, composed: true,
      }));
    });
  }
  setConfig(config) {
    this._config = validateDashboardConfig(config, this._hass?.locale?.language);
    this._update();
  }
  set hass(hass) {
    this._hass = hass;
    this._update();
  }
  _update() {
    this._form.hass = this._hass;
    this._form.data = this._config;
    this._form.computeLabel = ({ name }) => dashboardText(this._hass?.locale?.language, `dashboard.${name}`);
  }
}

